#include <iostream>
#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    long long ans = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            string s1;
            for (int k = i; k <= j; ++k) {
                s1 += s[k];
            }

            if (s1.front() != s1.back()) {
                bool fl = true;
                for (int k = 1; k < static_cast<int>(s1.size()) - 2; ++k) {
                    if (s1[k] >= 'A' && s1[k] <= 'Z') {
                        fl = false;
                    }
                }

                if (fl) {
                    ++ans;
                }
            }
        }
    }

    cout << ans;
    return 0;
}

